import React from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, Cell } from "recharts";
import { ArrowTrendingUpIcon } from "@heroicons/react/24/solid";

const COLORS = ["#3b82f6", "#10b981", "#f59e42", "#f43f5e", "#6366f1", "#fbbf24", "#14b8a6"];

const Overview = ({ goals, income }) => {
  const totalTarget = goals.reduce((sum, g) => sum + g.amount, 0);
  const totalSaved = goals.reduce((sum, g) => sum + g.saved, 0);
  const totalMonthlyNeeded = goals.reduce((sum, g) => sum + (g.monthlySavings || 0), 0);

  // Prepare data for stacked bar chart
  const chartData = goals.map((g, idx) => ({
    name: g.name,
    "Allocated": g.monthlySavings || 0,
    "Remaining": Math.max(income - (g.monthlySavings || 0), 0),
    color: COLORS[idx % COLORS.length],
  }));

  // Add a total bar for all goals
  chartData.push({
    name: "All Goals",
    Allocated: totalMonthlyNeeded,
    Remaining: Math.max(income - totalMonthlyNeeded, 0),
    color: "#6366f1",
  });

  return (
    <div className="bg-white rounded-xl shadow p-8 max-w-4xl mx-auto">
      <h2 className="text-2xl font-bold text-primary mb-4">Full Overview</h2>
      <div className="mb-6 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div>
          <div className="text-lg font-semibold">Total Savings Needed</div>
          <div className="text-2xl font-bold text-primary">${totalTarget.toLocaleString()}</div>
        </div>
        <div>
          <div className="text-lg font-semibold">Total Saved</div>
          <div className="text-2xl font-bold text-emerald-600">${totalSaved.toLocaleString()}</div>
        </div>
        <div>
          <div className="text-lg font-semibold">Monthly Disposable Income</div>
          <div className="text-2xl font-bold text-blue-600">${income.toLocaleString()}</div>
        </div>
      </div>
      {/* Prominent summary for each goal */}
      <div className="mb-6">
        {goals.map((g, idx) => (
          <div key={g.id} className="flex items-center gap-2 text-md font-semibold text-blue-700 mb-1">
            <ArrowTrendingUpIcon className="h-5 w-5 text-emerald-500" />
            For <span className="text-primary">{g.name}</span>: Put aside <span className="text-emerald-600">${g.monthlySavings ? g.monthlySavings.toLocaleString() : 0}</span> per month
          </div>
        ))}
      </div>
      <div className="h-80 mb-8">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
            <XAxis dataKey="name" tick={{ fontSize: 12 }} />
            <YAxis tick={{ fontSize: 12 }} />
            <Tooltip />
            <Legend payload={[
              { value: 'Allocated (Monthly Needed)', type: 'square', color: '#3b82f6' },
              { value: 'Remaining Disposable Income', type: 'square', color: '#a5b4fc' },
            ]} />
            <Bar dataKey="Allocated" stackId="a" radius={[8, 8, 0, 0]}>
              {chartData.map((entry, idx) => (
                <Cell key={`cell-alloc-${idx}`} fill={entry.name === 'All Goals' ? '#6366f1' : entry.color} />
              ))}
            </Bar>
            <Bar dataKey="Remaining" stackId="a" fill="#a5b4fc" radius={[8, 8, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-full text-sm text-left border-t">
          <thead>
            <tr className="bg-blue-50">
              <th className="px-4 py-2 font-semibold">Goal</th>
              <th className="px-4 py-2 font-semibold">Deadline</th>
              <th className="px-4 py-2 font-semibold">Months Remaining</th>
              <th className="px-4 py-2 font-semibold text-emerald-700 flex items-center gap-1">
                <ArrowTrendingUpIcon className="h-4 w-4 inline text-emerald-500" /> Monthly Needed
              </th>
            </tr>
          </thead>
          <tbody>
            {goals.map((g, idx) => {
              // Calculate months remaining
              const now = new Date();
              const deadline = new Date(g.deadline);
              const monthsRemaining = Math.max(
                1,
                (deadline.getFullYear() - now.getFullYear()) * 12 +
                  (deadline.getMonth() - now.getMonth())
              );
              return (
                <tr key={g.id} className="border-b hover:bg-blue-50/50">
                  <td className="px-4 py-2 font-medium text-primary">{g.name}</td>
                  <td className="px-4 py-2">{g.deadline}</td>
                  <td className="px-4 py-2">{monthsRemaining}</td>
                  <td className="px-4 py-2 text-emerald-700 font-bold flex items-center gap-1">
                    <ArrowTrendingUpIcon className="h-4 w-4 text-emerald-500" />
                    ${g.monthlySavings ? g.monthlySavings.toLocaleString() : 0}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Overview;
